import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table. Columns are private bookkeeping; see jobs.ts for the public shape. */
export interface JobRow {
  seq: number;
  id: string;
  idempotency_key: string | null;
  input: string;
  steps: number;
  fail_attempts: number;
  status: JobStatus;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  /** Epoch milliseconds before which a queued job must not be claimed (retry back-off). */
  eligible_at: number;
}

/** Opens the SQLite database shared by the server and worker processes and ensures the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  initSchema(db);
  return db;
}

/** Idempotent: safe to run from either process at any time. Never resets existing rows. */
function initSchema(db: DatabaseSync): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY,
      id TEXT NOT NULL UNIQUE,
      idempotency_key TEXT UNIQUE,
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
      attempts INTEGER NOT NULL DEFAULT 0,
      completed INTEGER NOT NULL DEFAULT 0,
      output TEXT,
      error TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      eligible_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, seq);
    CREATE TABLE IF NOT EXISTS heartbeat (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      at INTEGER NOT NULL
    );
  `);
}

/**
 * Runs `fn` in a BEGIN IMMEDIATE transaction. `fn` must be synchronous: a transaction must never
 * stay open across an await. Rolls back if `fn` throws.
 */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
  try {
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // transaction already ended
    }
    throw e;
  }
  return result;
}

/** Reads the first row of a query, typed as a job row. */
export function oneJob(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

export function allJobs(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): JobRow[] {
  return db.prepare(sql).all(...params) as unknown as JobRow[];
}

/** Writes the worker heartbeat. Only the worker calls this. */
export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare('INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at').run(now);
}

/** Returns the time of the last heartbeat, or undefined if none has ever been written or it was cleared. */
export function readHeartbeat(db: DatabaseSync): number | undefined {
  const row = db.prepare('SELECT at FROM heartbeat WHERE id = 1').get() as { at: number } | undefined;
  return row?.at;
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM heartbeat').run();
}

