import type { JobRow, JobStatus } from './db.ts';

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
/** A job gets at most this many processing attempts before it is marked failed. */
export const MAX_ATTEMPTS = 3;
/** Back-off before a failed attempt is retried. Must lie within 250 ms to 2 s. */
export const RETRY_DELAY_MS = 500;

export interface SubmitPayload {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

/** The job representation returned by every endpoint that returns a job. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toPublicJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

export function isIdempotencyKey(value: string): boolean {
  return IDEMPOTENCY_KEY_RE.test(value);
}

/** True for `application/json` with any case and any parameters, such as `; charset=utf-8`. */
export function isJsonContentType(contentType: string | undefined): boolean {
  if (contentType === undefined) return false;
  return contentType.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isIntegerIn(value: unknown, min: number, max: number): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/**
 * Validates a JSON request body. Collects every error rather than stopping at the first.
 * Returns the normalized payload only when there are no errors.
 */
export function validateBody(text: string): { fields: FieldError[]; payload?: SubmitPayload } {
  if (text.trim() === '') return { fields: [{ field: 'body', message: 'Request body must be a JSON object.' }] };
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { fields: [{ field: 'body', message: 'Request body is not valid JSON.' }] };
  }
  if (!isPlainObject(parsed)) return { fields: [{ field: 'body', message: 'Request body must be a JSON object.' }] };

  const fields: FieldError[] = [];
  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  let input = '';
  if (!Object.hasOwn(parsed, 'input')) {
    fields.push({ field: 'input', message: 'input is required.' });
  } else if (typeof parsed.input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string.' });
  } else if (parsed.input.length < 1 || parsed.input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters.' });
  } else if (parsed.input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace.' });
  } else {
    input = parsed.input;
  }

  let steps = DEFAULT_STEPS;
  if (Object.hasOwn(parsed, 'steps')) {
    if (isIntegerIn(parsed.steps, 1, 20)) steps = parsed.steps as number;
    else fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20.' });
  }

  let failAttempts = DEFAULT_FAIL_ATTEMPTS;
  if (Object.hasOwn(parsed, 'failAttempts')) {
    if (isIntegerIn(parsed.failAttempts, 0, 5)) failAttempts = parsed.failAttempts as number;
    else fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5.' });
  }

  if (fields.length > 0) return { fields };
  return { fields, payload: { input, steps, failAttempts } };
}

