import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { clearHeartbeat, oneJob, openDatabase, transaction, writeHeartbeat, type JobRow } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS } from './jobs.ts';

const STEP_MS = 100;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** A job claimed for one attempt. `attempts` is the number of the attempt being run. */
interface Attempt {
  seq: number;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
}

function heartbeat(): void {
  try {
    writeHeartbeat(db, Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e instanceof Error ? e.message : e);
  }
}

/**
 * Claims the next piece of work in one transaction. An interrupted `running` job (left behind by a
 * previous worker) is resumed under its existing attempt number. Otherwise the oldest eligible queued
 * job starts a new attempt.
 */
function claimNext(): Attempt | undefined {
  return transaction(db, () => {
    const now = new Date().toISOString();
    const running = oneJob(db, `SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1`);
    if (running) {
      db.prepare(`UPDATE jobs SET completed = 0, updated_at = ? WHERE seq = ?`).run(now, running.seq);
      return toAttempt(running);
    }
    const queued = oneJob(
      db,
      `SELECT * FROM jobs WHERE status = 'queued' AND eligible_at <= ? ORDER BY seq LIMIT 1`,
      Date.now(),
    );
    if (!queued) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL,
                       updated_at = ? WHERE seq = ?`,
    ).run(now, queued.seq);
    return toAttempt({ ...queued, attempts: queued.attempts + 1 });
  });
}

function toAttempt(row: JobRow): Attempt {
  return { seq: row.seq, input: row.input, steps: row.steps, failAttempts: row.fail_attempts, attempts: row.attempts };
}

/** Records a failed attempt: requeue with a back-off, or mark the job failed after the last attempt. */
function recordFailure(job: Attempt): void {
  const now = new Date().toISOString();
  transaction(db, () => {
    if (job.attempts < MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'queued', completed = 0, output = NULL, error = NULL,
                         eligible_at = ?, updated_at = ?
         WHERE seq = ? AND status = 'running' AND attempts = ?`,
      ).run(Date.now() + RETRY_DELAY_MS, now, job.seq, job.attempts);
    } else {
      db.prepare(
        `UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = 'transient failure', updated_at = ?
         WHERE seq = ? AND status = 'running' AND attempts = ?`,
      ).run(now, job.seq, job.attempts);
    }
  });
}

/**
 * Runs one attempt. Returns false if shutdown interrupted it, leaving the job `running` so the next
 * worker resumes it.
 */
async function runAttempt(job: Attempt): Promise<boolean> {
  if (job.attempts <= job.failAttempts) {
    // Simulated transient failure at the first step, before any progress is recorded.
    await sleep(STEP_MS);
    if (stopping) return false;
    recordFailure(job);
    return true;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return false;
    const now = new Date().toISOString();
    if (step < job.steps) {
      db.prepare(
        `UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ? AND status = 'running' AND attempts = ?`,
      ).run(step, now, job.seq, job.attempts);
    } else {
      // The final step and the completed state are committed together.
      db.prepare(
        `UPDATE jobs SET status = 'completed', completed = ?, output = ?, updated_at = ?
         WHERE seq = ? AND status = 'running' AND attempts = ?`,
      ).run(job.steps, job.input.toUpperCase(), now, job.seq, job.attempts);
    }
  }
  return true;
}

async function main(): Promise<void> {
  heartbeat();
  const beats = setInterval(heartbeat, HEARTBEAT_MS);
  console.log('worker started');

  try {
    while (!stopping) {
      let job: Attempt | undefined;
      try {
        job = claimNext();
      } catch (e) {
        console.error('claim failed:', e instanceof Error ? e.message : e);
        await sleep(POLL_MS * 5);
        continue;
      }
      if (!job) {
        await sleep(POLL_MS);
        continue;
      }
      try {
        await runAttempt(job);
      } catch (e) {
        console.error('attempt failed:', e instanceof Error ? e.message : e);
        await sleep(POLL_MS * 5);
      }
    }
  } finally {
    clearInterval(beats);
  }

  try {
    clearHeartbeat(db);
  } catch {
    // best effort: the heartbeat goes stale on its own
  }
  db.close();
  console.log('worker stopped');
  process.exit(0);
}

void every;
main().catch((e: unknown) => {
  console.error('worker crashed:', e instanceof Error ? e.stack ?? e.message : e);
  process.exit(1);
});

