import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { allJobs, oneJob, openDatabase, readHeartbeat, transaction, type JobRow } from './db.ts';
import {
  isIdempotencyKey,
  isJsonContentType,
  toPublicJob,
  validateBody,
  type FieldError,
  type SubmitPayload,
} from './jobs.ts';

const HEARTBEAT_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const DRAIN_MS = 5_000;

const db: DatabaseSync = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  extraHeaders: Record<string, string> = {},
): void {
  const error: Record<string, unknown> = { code, message };
  if (fields !== undefined) error.fields = fields;
  sendJson(res, status, { error }, extraHeaders);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!tooLarge) chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

/** Returns true if the method is allowed; otherwise sends 405 and returns false. */
function allowMethods(req: IncomingMessage, res: ServerResponse, allowed: string[]): boolean {
  if (req.method !== undefined && allowed.includes(req.method)) return true;
  sendError(res, 405, 'method_not_allowed', `Method ${req.method ?? ''} is not allowed here.`, undefined, { allow: allowed.join(', ') });
  return false;
}

type SubmitOutcome = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

/** Creates a job, or replays/conflicts with an existing job that used the same idempotency key. */
function submit(payload: SubmitPayload, key: string | undefined): SubmitOutcome {
  return transaction(db, () => {
    if (key !== undefined) {
      const existing = oneJob(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', key);
      if (existing) {
        const same =
          existing.input === payload.input &&
          existing.steps === payload.steps &&
          existing.fail_attempts === payload.failAttempts;
        return same ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, idempotency_key, input, steps, fail_attempts, status, attempts, completed,
                         output, error, created_at, updated_at, eligible_at)
       VALUES (?, ?, ?, ?, ?, 'queued', 0, 0, NULL, NULL, ?, ?, ?)`,
    ).run(id, key ?? null, payload.input, payload.steps, payload.failAttempts, now, now, Date.now());
    const row = oneJob(db, 'SELECT * FROM jobs WHERE id = ?', id)!;
    return { kind: 'created', row };
  });
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const fields: FieldError[] = [];

  const rawKey = req.headers['idempotency-key'];
  let key: string | undefined;
  if (rawKey !== undefined) {
    if (isIdempotencyKey(rawKey)) key = rawKey;
    else fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  let payload: SubmitPayload | undefined;
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (tooLarge) {
    fields.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    const result = validateBody(text);
    fields.push(...result.fields);
    payload = result.payload;
  }

  if (fields.length > 0 || payload === undefined) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);
    return;
  }

  const outcome = submit(payload, key);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, toPublicJob(outcome.row));
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = oneJob(db, 'SELECT * FROM jobs WHERE id = ?', id);
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  sendJson(res, 200, toPublicJob(row));
}

function handleListJobs(res: ServerResponse): void {
  const rows = allJobs(db, 'SELECT * FROM jobs ORDER BY seq DESC');
  sendJson(res, 200, { jobs: rows.map(toPublicJob) });
}

function handleHealth(res: ServerResponse): void {
  const at = readHeartbeat(db);
  const up = at !== undefined && Date.now() - at <= HEARTBEAT_FRESH_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/') {
    if (!allowMethods(req, res, ['GET'])) return;
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (!allowMethods(req, res, ['GET'])) return;
    handleHealth(res);
    return;
  }
  if (pathname === '/api/jobs') {
    if (!allowMethods(req, res, ['GET', 'POST'])) return;
    if (req.method === 'POST') await handleCreateJob(req, res);
    else handleListJobs(res);
    return;
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (!allowMethods(req, res, ['GET'])) return;
    handleGetJob(res, decodeURIComponent(match[1]!));
    return;
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e instanceof Error ? e.message : e);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'Internal server error.');
    }
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), DRAIN_MS).unref();
  setTimeout(() => process.exit(0), DRAIN_MS + 1_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

